<?php

namespace App\Http\Controllers;

use App\Support\CheckoutAvailability;
use Illuminate\Http\RedirectResponse;
use Stripe\Exception\ExceptionInterface as StripeException;

/**
 * Sends the account owner to the Stripe Customer Portal.
 *
 * The portal is Stripe's own hosted page for managing a subscription: changing
 * payment methods, downloading invoices, and cancelling. Kudosly does not
 * rebuild any of that.
 *
 * The session is created entirely on the server. The customer is the
 * authenticated account's own Stripe customer, and the return URL is
 * generated by the application. Nothing the browser submits is trusted, so a
 * request cannot open a portal session for somebody else's customer.
 */
class BillingPortalController extends Controller
{
    /**
     * Open the Stripe Customer Portal for the authenticated account.
     */
    public function __invoke(): RedirectResponse
    {
        $user = auth()->user();

        if (! CheckoutAvailability::available()) {
            return back()->withErrors([
                'billing' => 'Billing is not available right now. Please try again later.',
            ]);
        }

        // The portal is only useful to an account that has something to
        // manage. An account with no Stripe customer has no subscription, so
        // there is nothing for Stripe to show.
        if (! is_string($user->stripe_id) || $user->stripe_id === '') {
            return back()->withErrors([
                'billing' => 'There is no billing account to manage yet.',
            ]);
        }

        try {
            return $user->redirectToBillingPortal(route('billing'));
        } catch (StripeException) {
            // Stripe refused the request, was unreachable, or rejected the
            // credentials. Nothing about the subscription changes.
            return back()->withErrors([
                'billing' => 'We could not open the billing portal. Please try again.',
            ]);
        }
    }
}
